#!/usr/bin/env python3
"""Dagger/positivity gate on the exact physical n=8 selected kernel."""
import json,sys,math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'research/benincasa/.tmp_sympy'));import sympy as s
src=json.loads((ROOT/'research/nima/results/nnmhv-kernel-wall-tail-boundary.json').read_text());K=s.Matrix([[s.sympify(x) for x in row] for row in src['kernel_matrix']]);Kd=K.T;H=s.simplify((K+Kd)/2);rho=s.simplify(Kd*K);comm=s.simplify(K*Kd-Kd*K);one=s.ones(K.rows,1);amp=s.factor((one.T*K*one)[0]);born=s.factor((one.T*rho*one)[0]/K.rows);principal=[s.factor(rho[:q,:q].det()) for q in range(1,K.rows+1)];evals=[complex(v) for v in H.evalf().eigenvals().keys()];checks={'kernel_is_triangular_amplitude_not_hermitian':K!=Kd,'kernel_is_not_normal':comm!=s.zeros(K.rows),'quadratic_completion_is_hermitian':rho==rho.T,'quadratic_completion_positive_semidefinite':all(float(v)>=-1e-12 for v in principal),'quadratic_completion_rank_matches_kernel':rho.rank()==K.rank(),'linear_augmentation_matches_stored_scalar':str(amp)==src['scalar_full'],'born_readout_differs_from_linear_amplitude':s.factor(born-amp)!=0}
out={'schema':'marici.nima.nnmhv-physical-kernel-star-gate.v1','n':src['n'],'kernel_rank':K.rank(),'rho_rank':rho.rank(),'linear_amplitude':str(amp),'uniform_born_quadratic':str(born),'hermitian_part_eigenvalues':[{'real':v.real,'imag':v.imag} for v in evals],'rho_leading_principal_minors':[str(v) for v in principal],'checks':checks,'passed':all(checks.values()),'conclusion':'The physical canonical kernel is an amplitude operator, not a Hermitian or positive state. The source-derived dagger produces a canonical positive operator rho=K^dagger K, but its Born readout is a new quadratic observable and is not the original amplitude.','implication':'Quantum positivity is available canonically only after quadratic completion; it is not already obeyed by canonical-form weights.'};p=ROOT/'research/nima/results/nnmhv-physical-kernel-star-gate.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
